+	writeValidationWarningLog(ctx, params, siteIDStr, domain, issues, repairs, logger)
@@ new @@
+const validationWarningErrorCode = "CONTENT_VALIDATION_WARNING_DETAIL"
+func survivingWarnings(issues []ValidationIssue, repairs []datahelpers.LinkRepair) []map[string]string { ... }
+func writeValidationWarningLog(ctx context.Context, params ActionParams, siteIDStr string, domain string, issues []ValidationIssue, repairs []datahelpers.LinkRepair, logger *zap.Logger) {
+	if params.DB == nil { return }
+	surviving := survivingWarnings(issues, repairs)
+	if len(surviving) == 0 { return }
+	var siteIDArg string
+	if siteIDStr != "" {
+		if id, err := uuid.Parse(siteIDStr); err == nil { siteIDArg = id.String() }
+	}
+	if !LogActionEntry(ctx, params, agenterrors.Entry{
+		SiteID: siteIDArg, Domain: domain,
+		AgentType: "page-build-handler", StepName: "validate_content", Action: "validate_page_content",
+		ErrorMessage: fmt.Sprintf("Valid build carried %d unrepaired warning(s); see context.issues for detail", len(surviving)),
+		ErrorCode: validationWarningErrorCode, Severity: "warning",
+		Context: map[string]interface{}{
+			"warning_count": len(surviving),
+			"issues": surviving,
+			"page_name": datahelpers.ExtractNestedFieldString(params.CollectedData, "page_record.name"),
+			"page_url":  datahelpers.ExtractNestedFieldString(params.CollectedData, "page_record.url"),
+		},
+	}, logger) { return }
+}
